defmodule CredoTypespecTest do
  @spec foo(integer, integer) :: integer
  @doc "some docs for foo/2"
  def foo(a, b), do: a + b

  @spec foo(integer) :: integer
  def foo(a), do: a
end

defmodule CredoTypespecTest do
  @spec foo(a, a) :: a when a: integer
  @doc "some docs for foo/2"
  def foo(a, b), do: a + b
end

defmodule CredoTypespecTest do
  @spec foo(integer) :: integer
  def foo(a), do: a

  @spec foo(integer) :: integer
  defp foo(a), do: a
end
